  "milestones": [
    {
      "task": "find brown_wool",
      "milestone_id": "find_brown_wool",
      "description": "Uses position_near_with_facing because this is a 'find' task — the player must navigate near the brown wool structure and face it to demonstrate they have located it. Target is the center of the brown wool tower at (4, 2, 4), max_distance=16 allows detection from moderate range, facing_tolerance=60 ensures the player is actually looking at it.",
